sidebarCSS:
#root.root {
  --popup-bg: #f0e8da;
  --frame-bg: #f8f4e9;
  --toolbar-bg: #f0e8da;
  --tabs-normal-bg: #f0e8da;
  --tabs-activated-bg: #f0e8da;
  --tabs-normal-fg: #403732;
  --tabs-activated-fg: #403732;
  --nav-btn-fg: #6b564b;
  --nav-btn-accent: #dbb4d3;
  --accent: #dbb4d3;
  --status-notice: #90cdde;
  --status-active: #9bb0de;
  --status-err: #cf8282;
  --status-ok: #9ccc96;
  --general-border-radius: 8px;
  --toolbar-color: #6b564b;
}

@media (prefers-color-scheme: dark) {
  #root.root {
    --popup-bg: #4f453f;
    --frame-bg: #6b564b;
    --toolbar-bg: #4f453f;
    --tabs-normal-bg: #4f453f;
    --tabs-activated-bg: #4f453f;
    --tabs-normal-fg: #f0e8da;
    --tabs-activated-fg: #f0e8da;
    --nav-btn-fg: #decec1;
    --toolbar-color: #decec1;
  }
}

[data-color="blue"]      { --color: #9bb0de; }
[data-color="turquoise"] { --color: #90cdde; }
[data-color="green"]     { --color: #9ccc96; }
[data-color="yellow"]    { --color: #e3cd7f; }
[data-color="orange"]    { --color: #d4a266; }
[data-color="red"]       { --color: #cf8282; }
[data-color="pink"]      { --color: #edb7ca; }
[data-color="purple"]    { --color: #aa99d1; }
[data-color="toolbar"]   { --color: var(--toolbar-color); }

.PanelButton[data-color] {
  --nav-btn-fg: var(--pc) !important;
}
.PanelButton[data-color] svg {
  fill: var(--pc) !important;
  color: var(--pc) !important;
}

.Tab[data-color] {
  --tabs-indicator-bg: var(--pc) !important;
}
